public static void check(Solution solution) {
    assert Arrays.equals(solution.removeAnagrams(new int[]{"abc","cab","bca","xyz","zyx","yxz"}), new int[]{'abc', 'xyz'});
    assert Arrays.equals(solution.removeAnagrams(new int[]{"abc","cba","bca","xyz","zyx"}), new int[]{'abc', 'xyz'});
    assert Arrays.equals(solution.removeAnagrams(new int[]{"unique","words","here","now"}), new int[]{'unique', 'words', 'here', 'now'});
    assert Arrays.equals(solution.removeAnagrams(new int[]{"test","sett","tset","ttew"}), new int[]{'test', 'ttew'});
    assert Arrays.equals(solution.removeAnagrams(new int[]{"same","same","same","same","same"}), new int[]{'same'});
    assert Arrays.equals(solution.removeAnagrams(new int[]{"a","b","c","d","e"}), new int[]{'a', 'b', 'c', 'd', 'e'});
    assert Arrays.equals(solution.removeAnagrams(new int[]{"aabbcc","abcabc","bcaacb","bacbac","cababc"}), new int[]{'aabbcc'});
    assert Arrays.equals(solution.removeAnagrams(new int[]{"test","sett","tset","stet","ttes"}), new int[]{'test'});
    assert Arrays.equals(solution.removeAnagrams(new int[]{"one","two","three","four","five","six","seven","eight","nine","ten"}), new int[]{'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten'});
    assert Arrays.equals(solution.removeAnagrams(new int[]{"hello","billion","oellh","llheo","note","tone"}), new int[]{'hello', 'billion', 'oellh', 'note'});
